import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"61、【中孚】 兑下巽上","description":"横渠易说 - 61、【中孚】 兑下巽上","frontmatter":{"title":"61、【中孚】 兑下巽上","description":"横渠易说 - 61、【中孚】 兑下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/063.md","filePath":"zh/classics/hengqu/063.md"}'),l={name:"zh/classics/hengqu/063.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_61、【中孚】-兑下巽上" tabindex="-1">61、【中孚】 兑下巽上 <a class="header-anchor" href="#_61、【中孚】-兑下巽上" aria-label="Permalink to “61、【中孚】 兑下巽上”">​</a></h1><h3 id="彖曰-中孚-柔在内而刚得中-说而巽-孚乃化邦也。-豚鱼吉-信及豚鱼也-利涉大川-乘木舟处也。中孚以利贞-乃应乎天也。" tabindex="-1">彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。“豚鱼吉”，信及豚鱼也；“利涉大川”，乘木舟处也。中孚以利贞，乃应乎天也。 <a class="header-anchor" href="#彖曰-中孚-柔在内而刚得中-说而巽-孚乃化邦也。-豚鱼吉-信及豚鱼也-利涉大川-乘木舟处也。中孚以利贞-乃应乎天也。" aria-label="Permalink to “彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。“豚鱼吉”，信及豚鱼也；“利涉大川”，乘木舟处也。中孚以利贞，乃应乎天也。”">​</a></h3><h3 id="象曰-泽上有风-中孚-君子以议狱缓死。" tabindex="-1">象曰：泽上有风，中孚，君子以议狱缓死。 <a class="header-anchor" href="#象曰-泽上有风-中孚-君子以议狱缓死。" aria-label="Permalink to “象曰：泽上有风，中孚，君子以议狱缓死。”">​</a></h3><p>中孚，上巽施之，下悦承之，其中必有感化而出焉者。盖孚者覆乳之象，有必生之理，信且正，天之道也。</p><h3 id="初九-虞吉-有他不燕。-象曰-初九虞吉-志未变也。" tabindex="-1">初九，虞吉，有他不燕。 象曰：“初九虞吉”，志未变也。 <a class="header-anchor" href="#初九-虞吉-有他不燕。-象曰-初九虞吉-志未变也。" aria-label="Permalink to “初九，虞吉，有他不燕。 象曰：“初九虞吉”，志未变也。”">​</a></h3><p>为信之始，其信未孚，而志应在四，进有二三，刚柔之间，非以礼自防，使为众所信，取悔之道也。故必防其萌，使志不乱，孚交如则威如乃吉。</p><h3 id="九二-鸣鹤在阴-其子和之。我有好爵-吾与尔靡之。-象曰-其子和之-中心愿也。" tabindex="-1">九二，鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。 象曰：“其子和之”，中心愿也。 <a class="header-anchor" href="#九二-鸣鹤在阴-其子和之。我有好爵-吾与尔靡之。-象曰-其子和之-中心愿也。" aria-label="Permalink to “九二，鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。 象曰：“其子和之”，中心愿也。”">​</a></h3><p>居中体巽，无所私系，德必有邻，物愿所归，位以德致，为五所任，故曰“与尔靡之”。靡，偃也，顺从之也。</p><h3 id="六三-得敌-或鼓或罢-或泣或歌。-象曰-或鼓或罢-位不当也。" tabindex="-1">六三，得敌，或鼓或罢，或泣或歌。 象曰：“或鼓或罢”，位不当也。 <a class="header-anchor" href="#六三-得敌-或鼓或罢-或泣或歌。-象曰-或鼓或罢-位不当也。" aria-label="Permalink to “六三，得敌，或鼓或罢，或泣或歌。 象曰：“或鼓或罢”，位不当也。”">​</a></h3><p>处非所安，物之所恶，刚而乘之，柔不相比，进退之际，惟敌是求，不恒其德，莫非己致。一作惟敌是得，故求之云云。</p><h3 id="六四-月几望-马匹亡-无咎。-象曰-马匹亡-绝类上也。" tabindex="-1">六四，月几望，马匹亡，无咎。 象曰：“马匹亡”，绝类上也。 <a class="header-anchor" href="#六四-月几望-马匹亡-无咎。-象曰-马匹亡-绝类上也。" aria-label="Permalink to “六四，月几望，马匹亡，无咎。 象曰：“马匹亡”，绝类上也。”">​</a></h3><p>诚以接物，体巽居柔，阴德之盛美者也。阴德盛美，物所愿交，故必一其所应，绝类于上，使阴不疑阳，如月近望而不过于盈，可以无咎。一作免咎。</p><h3 id="九五-有孚挛如-无咎。-象曰-有孚挛如-位正当也。" tabindex="-1">九五，有孚挛如，无咎。 象曰：“有孚挛如”，位正当也。 <a class="header-anchor" href="#九五-有孚挛如-无咎。-象曰-有孚挛如-位正当也。" aria-label="Permalink to “九五，有孚挛如，无咎。 象曰：“有孚挛如”，位正当也。”">​</a></h3><p>处乎盛位而信不交物，未免于咎也。</p><h3 id="上九-翰音登于天-贞凶。-象曰-翰音登于天-何可长也" tabindex="-1">上九，翰音登于天，贞凶。 象曰：“翰音登于天”，何可长也! <a class="header-anchor" href="#上九-翰音登于天-贞凶。-象曰-翰音登于天-何可长也" aria-label="Permalink to “上九，翰音登于天，贞凶。 象曰：“翰音登于天”，何可长也!”">​</a></h3><p>处信之极，好居物上，信而无实，穷上必凶。一云：将变而为小过也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
